insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-slim-panel-4in-9w', 'GSW-LEDSLIMPAN', '4" LED Slim Panel 9W – Dimmable', 'residential-lighting', 'led-slim-panel', 14.5, 18, false, 'Ultra-thin recessed wafer panel with integrated junction box and smooth dimming to 10%.', 'Ultra-thin recessed wafer panel with integrated junction box and smooth dimming to 10%.', '["9W | 720 lm","3000K / 4000K / 5000K selectable","120V, dimmable to 10%","cULus certified | 5-year warranty"]'::jsonb, 'in-stock', '4" LED Slim Panel 9W – Dimmable', 'Buy the 4" LED Slim Panel 9W – Dimmable wholesale in Canada. 9W | 720 lm — cULus/DLC certified, flat $30 shipping.', 'The 4" LED Slim Panel 9W – Dimmable is an ultra-thin LED panel light designed for fast residential installs where a traditional pot light housing will not fit. 9W | 720 lm, with selectable colour temperature so the whole home matches from room to room. Because GSW is a lighting distributor serving Mississauga, Toronto and the wider GTA, contractors can pick these panels up at the counter or have them shipped flat-rate anywhere in Canada — at true wholesale pricing.', '[{"q":"Do these slim panels need a housing?","a":"No — the driver and junction box are built into the panel, so it mounts directly to drywall with spring clips. They are IC-rated and wet-location approved, which also makes them suitable for showers and soffits."},{"q":"Are the slim panels dimmable?","a":"Yes, most models dim smoothly to 10% with standard TRIAC wall dimmers. If your project uses 0-10V dimming, call the counter and we will match the right driver."}]'::jsonb, '/images/extras/8-inch-slim.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-slim-panel-6in-12w', 'GSW-LEDSLIMPANEL', '6" LED Slim Panel 12W – 5CCT', 'residential-lighting', 'led-slim-panel', 18.75, 24, false, '6-inch edge-lit slim panel with five selectable colour temperatures, ideal for whole-home retrofits.', '6-inch edge-lit slim panel with five selectable colour temperatures, ideal for whole-home retrofits.', '["12W | 960 lm","2700K–5000K selectable CCT","120V, IC-rated, wet-location approved","50,000 hr life | cULus listed"]'::jsonb, 'in-stock', '6" LED Slim Panel 12W – 5CCT Canada', 'Buy the 6" LED Slim Panel 12W – 5CCT wholesale in Canada. 12W | 960 lm — cULus/DLC certified, flat $30 shipping.', 'The 6" LED Slim Panel 12W – 5CCT is an ultra-thin LED panel light designed for fast residential installs where a traditional pot light housing will not fit. 12W | 960 lm, with selectable colour temperature so the whole home matches from room to room. Because GSW is a lighting distributor serving Mississauga, Toronto and the wider GTA, contractors can pick these panels up at the counter or have them shipped flat-rate anywhere in Canada — at true wholesale pricing.', '[{"q":"Do these slim panels need a housing?","a":"No — the driver and junction box are built into the panel, so it mounts directly to drywall with spring clips. They are IC-rated and wet-location approved, which also makes them suitable for showers and soffits."},{"q":"Are the slim panels dimmable?","a":"Yes, most models dim smoothly to 10% with standard TRIAC wall dimmers. If your project uses 0-10V dimming, call the counter and we will match the right driver."}]'::jsonb, '/images/extras/3pro.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-gimbal-3in-8w', 'GSW-LEDGIMBAL3', '3" LED Gimbal 8W – Adjustable', 'residential-lighting', 'led-gimbals', 16.25, null, false, 'Compact 3-inch gimbal with 35° tilt for accent and sloped-ceiling applications.', 'Compact 3-inch gimbal with 35° tilt for accent and sloped-ceiling applications.', '["8W | 640 lm","3000K/4000K/5000K selectable","35° tilt, 360° swivel","cETLus listed | 5-year warranty"]'::jsonb, 'in-stock', '3" LED Gimbal 8W – Adjustable', 'Buy the 3" LED Gimbal 8W – Adjustable wholesale in Canada. 8W | 640 lm — cULus/DLC certified, flat $30 shipping.', 'The 3" LED Gimbal 8W – Adjustable is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. 8W | 640 lm in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/extras/h2.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-gimbal-4in-10w', 'GSW-LEDGIMBAL4', '4" LED Gimbal 10W – Deep Baffle', 'residential-lighting', 'led-gimbals', 19.5, null, false, 'Deep-baffle 4-inch gimbal downlight delivering low-glare directional light for feature walls.', 'Deep-baffle 4-inch gimbal downlight delivering low-glare directional light for feature walls.', '["10W | 800 lm","3500K, 90+ CRI","120V, TRIAC dimmable","cULus certified | IC-rated"]'::jsonb, 'in-stock', '4" LED Gimbal 10W – Deep Baffle', 'Buy the 4" LED Gimbal 10W – Deep Baffle wholesale in Canada. 10W | 800 lm — cULus/DLC certified, flat $30 shipping.', 'The 4" LED Gimbal 10W – Deep Baffle is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. 10W | 800 lm in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/extras/h5.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-a19-bulb-shahab-series', 'GSW-LEDA19BULB', 'LED A19 Bulb 10W – Shahab Series', 'residential-lighting', 'led-ceiling-fixture', 100, null, true, 'High-output omnidirectional A19 lamp for ceiling fixtures and general residential lighting.', 'High-output omnidirectional A19 lamp for ceiling fixtures and general residential lighting.', '["10W | 1100 lm (100W equiv.)","3000K warm white","120V, non-dimmable","E26 base | cULus | 25,000 hr"]'::jsonb, 'in-stock', 'LED A19 Bulb 10W – Shahab Series', 'Buy the LED A19 Bulb 10W – Shahab Series wholesale in Canada. 10W | 1100 lm (100W equiv.) — cULus/DLC certified, flat $30 shipping.', 'The LED A19 Bulb 10W – Shahab Series is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. 10W | 1100 lm (100W equiv.), with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/shahab.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-ceiling-fixture-14in-24w', 'GSW-LEDCEILING', '14" LED Ceiling Fixture 24W – Flush Mount', 'residential-lighting', 'led-ceiling-fixture', 32, 39, false, 'Low-profile round flush-mount fixture with frosted acrylic diffuser for hallways and bedrooms.', 'Low-profile round flush-mount fixture with frosted acrylic diffuser for hallways and bedrooms.', '["24W | 1800 lm","3000K/4000K/5000K selectable","120V, dimmable","cETLus | 5-year warranty"]'::jsonb, 'in-stock', '14" LED Ceiling Fixture 24W – Flus…', 'Buy the 14" LED Ceiling Fixture 24W – Flush Mount wholesale in Canada. 24W | 1800 lm — cULus/DLC certified, flat $30 shipping.', 'The 14" LED Ceiling Fixture 24W – Flush Mount is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. 24W | 1800 lm, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/extras/4pro.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-motion-sensor-security-30w', 'GSW-LEDMOTIONS', 'LED Motion Sensor Security Light 30W', 'residential-lighting', 'led-motion-sensor-light', 42, 55, false, 'Dual-head adjustable flood with 180° PIR motion detection for garages, entries and yards.', 'Dual-head adjustable flood with 180° PIR motion detection for garages, entries and yards.', '["30W | 3000 lm","5000K daylight","180° PIR, adjustable heads","IP65 | cULus certified"]'::jsonb, 'in-stock', 'LED Motion Sensor Security Light 3…', 'Buy the LED Motion Sensor Security Light 30W wholesale in Canada. 30W | 3000 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Motion Sensor Security Light 30W is a motion-activated LED security light that switches on when it matters and stays off when it does not. 30W | 3000 lm with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-motion-bulkhead-15w', 'GSW-LEDMOTIONB', 'LED Motion Sensor Bulkhead 15W', 'residential-lighting', 'led-motion-sensor-light', 36, null, false, 'Oval bulkhead with integrated photocell and motion sensor for covered entries and stairwells.', 'Oval bulkhead with integrated photocell and motion sensor for covered entries and stairwells.', '["15W | 1200 lm","4000K neutral white","120-347V, photocell + PIR","cULus | IP54 rated"]'::jsonb, 'in-stock', 'LED Motion Sensor Bulkhead 15W', 'Buy the LED Motion Sensor Bulkhead 15W wholesale in Canada. 15W | 1200 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Motion Sensor Bulkhead 15W is a motion-activated LED security light that switches on when it matters and stays off when it does not. 15W | 1200 lm with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('jc-10w-a', 'GSW-JC10WA', 'JC-10W-A Under Cabinet Light Bar', 'residential-lighting', 'led-under-cabinet-light', 300, null, true, 'Linkable low-profile under-cabinet light bar with touch dimming and diffuser lens, JC-series.', 'Linkable low-profile under-cabinet light bar with touch dimming and diffuser lens, JC-series.', '["10W per bar | 700 lm","3000K warm white","Linkable up to 6 bars, touch dimmer","cETLus | 3-year warranty"]'::jsonb, 'in-stock', 'JC-10W-A Under Cabinet Light Bar', 'Buy the JC-10W-A Under Cabinet Light Bar wholesale in Canada. 10W per bar | 700 lm — cULus/DLC certified, flat $30 shipping.', 'The JC-10W-A Under Cabinet Light Bar is a low-profile LED under cabinet light that puts bright, even task light on counters without glare in your eyes. 10W per bar | 700 lm, and linkable bars let you run one continuous run under a full kitchen wall. Kitchen renovators and electrical contractors buy under cabinet lighting from GSW because our Mississauga counter stocks linkable kits, drivers and accessories together.', '[{"q":"Can the bars link together?","a":"Yes — most of our under cabinet bars link end-to-end with jumper cables, and all bars on one run share a single driver or wall plug."},{"q":"Hardwire or plug-in?","a":"Both options exist. Plug-in kits are fastest for renovations; hardwire junction-box models are preferred for new construction. We stock both."}]'::jsonb, '/images/products/jc-10w-a.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-under-cabinet-24in-14w', 'GSW-LEDUNDERCA', '24" LED Under Cabinet Light 14W', 'residential-lighting', 'led-under-cabinet-light', 24.5, 30, false, '24-inch linkable under-cabinet bar with hi-low-off switch for kitchens and workspaces.', '24-inch linkable under-cabinet bar with hi-low-off switch for kitchens and workspaces.', '["14W | 1000 lm","2700K/3000K/4000K options","Hardwire or plug-in, linkable","cULus certified"]'::jsonb, 'in-stock', '24" LED Under Cabinet Light 14W', 'Buy the 24" LED Under Cabinet Light 14W wholesale in Canada. 14W | 1000 lm — cULus/DLC certified, flat $30 shipping.', 'The 24" LED Under Cabinet Light 14W is a low-profile LED under cabinet light that puts bright, even task light on counters without glare in your eyes. 14W | 1000 lm, and linkable bars let you run one continuous run under a full kitchen wall. Kitchen renovators and electrical contractors buy under cabinet lighting from GSW because our Mississauga counter stocks linkable kits, drivers and accessories together.', '[{"q":"Can the bars link together?","a":"Yes — most of our under cabinet bars link end-to-end with jumper cables, and all bars on one run share a single driver or wall plug."},{"q":"Hardwire or plug-in?","a":"Both options exist. Plug-in kits are fastest for renovations; hardwire junction-box models are preferred for new construction. We stock both."}]'::jsonb, '/images/extras/puck-lights.jpg');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-strip-light-16ft-24v', 'GSW-LEDSTRIPLI', 'LED Strip Light 16.4ft – 24V 5050', 'residential-lighting', 'led-strip-light', 22.75, null, false, 'High-density 24V flexible LED tape with 3M backing for cove, toe-kick and accent runs.', 'High-density 24V flexible LED tape with 3M backing for cove, toe-kick and accent runs.', '["14.4W/m, 60 LED/m","3000K/4000K/6000K options","24V, cuttable every 4\"","cULus listed tape | IP20/IP65"]'::jsonb, 'in-stock', 'LED Strip Light 16.4ft – 24V 5050', 'Buy the LED Strip Light 16.4ft – 24V 5050 wholesale in Canada. 14.4W/m, 60 LED/m — cULus/DLC certified, flat $30 shipping.', 'The LED Strip Light 16.4ft – 24V 5050 is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. 14.4W/m, 60 LED/m on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/extras/strip-1.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-strip-channel-kit', 'GSW-LEDSTRIPCH', 'LED Strip + Aluminum Channel Kit 6.6ft', 'residential-lighting', 'led-strip-light', 34, 42, false, 'Complete channel kit with diffuser, end caps and mounting clips for a finished linear look.', 'Complete channel kit with diffuser, end caps and mounting clips for a finished linear look.', '["Includes 24V tape + driver","3000K/4000K/5000K","Frosted PC diffuser, deep profile","cETLus components"]'::jsonb, 'in-stock', 'LED Strip + Aluminum Channel Kit 6…', 'Buy the LED Strip + Aluminum Channel Kit 6.6ft wholesale in Canada. Includes 24V tape + driver — cULus/DLC certified, flat $30 shipping.', 'The LED Strip + Aluminum Channel Kit 6.6ft is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Includes 24V tape + driver on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/extras/strip-1.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-garden-path-light-5w', 'GSW-LEDGARDENP', 'LED Garden Path Light 5W', 'residential-lighting', 'led-outdoor-garden-light', 18.5, null, false, 'Low-voltage die-cast aluminum path light with seeded-glass shade for walkways and beds.', 'Low-voltage die-cast aluminum path light with seeded-glass shade for walkways and beds.', '["5W | 350 lm","2700K warm white","12V AC/DC, tool-free install","IP65 | cULus landscape listed"]'::jsonb, 'in-stock', 'LED Garden Path Light 5W Canada', 'Buy the LED Garden Path Light 5W wholesale in Canada. 5W | 350 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Garden Path Light 5W is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. 5W | 350 lm in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/extras/2-1.webp');
