insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-exit-sign-red', 'GSW-LEDEXITSIG', 'LED Exit Sign – Red Letters', 'commercial-lighting', 'exit-emergency-led-lighting', 24.5, 30, false, 'cULus-listed LED exit sign with red lettering, battery backup and universal mounting.', 'cULus-listed LED exit sign with red lettering, battery backup and universal mounting.', '["LED, 90-min battery backup","Red letters, single/double face","120/347V universal voltage","cULus listed | 5-year warranty"]'::jsonb, 'in-stock', 'LED Exit Sign – Red Letters Canada', 'Buy the LED Exit Sign – Red Letters wholesale in Canada. LED, 90-min battery backup — cULus/DLC certified, flat $30 shipping.', 'The LED Exit Sign – Red Letters is a cULus-listed exit and emergency lighting unit for code-compliant egress. LED, 90-min battery backup with 90-minute battery backup and universal mounting for walls and ceilings. Electrical contractors across Canada buy life-safety lighting from GSW because every unit we ship carries the certifications inspectors look for — and we stock them in depth.', '[{"q":"Does this meet Ontario Fire Code?","a":"Yes — our exit signs and emergency units are cULus listed to CSA 22.2 No. 141 with 90-minute battery backup, meeting Ontario Fire Code and OBC egress requirements. Certificates are available on request."},{"q":"Red or green letters?","a":"Ontario accepts both, but red is the most common choice locally. Most of our units accept either legend — tell us your preference when ordering."}]'::jsonb, null);
