insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-ufo-highbay-150w', 'GSW-LEDUFOHIGH', 'LED UFO High Bay 150W', 'industrial-lighting', 'led-ufo-high-bay', 108, 135, false, 'Round UFO high bay with glass lens and IP65 rating for warehouses up to 25 ft mounting.', 'Round UFO high bay with glass lens and IP65 rating for warehouses up to 25 ft mounting.', '["150W | 19,500 lm","5000K, 90° beam","120-277V, 0-10V dimmable","DLC Premium | cULus | IP65"]'::jsonb, 'in-stock', 'LED UFO High Bay 150W Canada', 'Buy the LED UFO High Bay 150W wholesale in Canada. 150W | 19,500 lm — cULus/DLC certified, flat $30 shipping.', 'The LED UFO High Bay 150W is an industrial LED UFO high bay for warehouses, gymnasiums and manufacturing floors. 150W | 19,500 lm with high-efficiency optics that put light on the floor, not the walls. GSW is a Canadian wholesale supplier of LED high bay lights, stocking 100W–240W UFOs with DLC Premium listings, hook mounts included, and flat $30 shipping to any industrial job site.', '[{"q":"How many high bays do I need for my warehouse?","a":"It depends on mounting height, racking layout and required foot-candles. As a guide, 150W UFOs on 4–5 metre centres serve most 6–8 metre warehouses well. Send us the floor plan and we will estimate quantities and spacing for free."},{"q":"UFO or linear high bay — which is better?","a":"UFOs are compact, quick to hang and ideal for open areas and lower ceilings. Linear high bays with aisle optics win in racked warehouses where light must travel down narrow aisles. Call us with the layout and we will recommend the right optic."}]'::jsonb, '/images/extras/screenshot_2-1.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-ufo-highbay-240w', 'GSW-LEDUFOHIGHBA', 'LED UFO High Bay 240W – High Output', 'industrial-lighting', 'led-ufo-high-bay', 156, null, false, '240W industrial UFO for high-rack warehouses, gymnasiums and manufacturing bays.', '240W industrial UFO for high-rack warehouses, gymnasiums and manufacturing bays.', '["240W | 31,200 lm","5000K daylight","120-277V, hook mount included","cULus | 10kV surge | 5-yr"]'::jsonb, 'in-stock', 'LED UFO High Bay 240W – High Output', 'Buy the LED UFO High Bay 240W – High Output wholesale in Canada. 240W | 31,200 lm — cULus/DLC certified, flat $30 shipping.', 'The LED UFO High Bay 240W – High Output is an industrial LED UFO high bay for warehouses, gymnasiums and manufacturing floors. 240W | 31,200 lm with high-efficiency optics that put light on the floor, not the walls. GSW is a Canadian wholesale supplier of LED high bay lights, stocking 100W–240W UFOs with DLC Premium listings, hook mounts included, and flat $30 shipping to any industrial job site.', '[{"q":"How many high bays do I need for my warehouse?","a":"It depends on mounting height, racking layout and required foot-candles. As a guide, 150W UFOs on 4–5 metre centres serve most 6–8 metre warehouses well. Send us the floor plan and we will estimate quantities and spacing for free."},{"q":"UFO or linear high bay — which is better?","a":"UFOs are compact, quick to hang and ideal for open areas and lower ceilings. Linear high bays with aisle optics win in racked warehouses where light must travel down narrow aisles. Call us with the layout and we will recommend the right optic."}]'::jsonb, '/images/extras/screenshot_2-1.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-linear-highbay-160w', 'GSW-LEDLINEARH', 'LED Linear High Bay 160W', 'industrial-lighting', 'led-linear-high-bay', 118, 148, false, 'Aisle-optics linear high bay for distribution centres and big-box retail racking.', 'Aisle-optics linear high bay for distribution centres and big-box retail racking.', '["160W | 20,800 lm","5000K, aisle optics","120-277V, 0-10V dimming","DLC Premium | cULus | 5-yr"]'::jsonb, 'in-stock', 'LED Linear High Bay 160W Canada', 'Buy the LED Linear High Bay 160W wholesale in Canada. 160W | 20,800 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Linear High Bay 160W is a linear LED high bay with aisle optics engineered for racked warehouses and big-box retail. 160W | 20,800 lm in a slim batten that chains or rods into place and links in continuous rows. Canadian warehouse contractors buy linear high bays wholesale from GSW for the DLC Premium efficiency and aisle-specific photometrics.', '[{"q":"What are aisle optics?","a":"Aisle optics concentrate the beam into a narrow rectangle that travels down storage aisles, lighting pallet faces evenly instead of wasting lumens on rack tops. They typically deliver 30%+ more usable light per watt in racked spaces."},{"q":"Can I dim these with occupancy sensors?","a":"Yes — with the 0-10V dimming versions paired with high-bay motion sensors, unoccupied aisles drop to a low level and return to full output on approach. The energy savings usually pay for the sensors within a year."}]'::jsonb, '/images/extras/untitled-1.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-linear-highbay-220w', 'GSW-LEDLINEARHIG', 'LED Linear High Bay 220W', 'industrial-lighting', 'led-linear-high-bay', 148, null, false, 'High-output linear high bay with lensed reflector for production floors and gymnasiums.', 'High-output linear high bay with lensed reflector for production floors and gymnasiums.', '["220W | 28,600 lm","4000K/5000K","120-347V, chain mount","cULus certified | IP65"]'::jsonb, 'in-stock', 'LED Linear High Bay 220W Canada', 'Buy the LED Linear High Bay 220W wholesale in Canada. 220W | 28,600 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Linear High Bay 220W is a linear LED high bay with aisle optics engineered for racked warehouses and big-box retail. 220W | 28,600 lm in a slim batten that chains or rods into place and links in continuous rows. Canadian warehouse contractors buy linear high bays wholesale from GSW for the DLC Premium efficiency and aisle-specific photometrics.', '[{"q":"What are aisle optics?","a":"Aisle optics concentrate the beam into a narrow rectangle that travels down storage aisles, lighting pallet faces evenly instead of wasting lumens on rack tops. They typically deliver 30%+ more usable light per watt in racked spaces."},{"q":"Can I dim these with occupancy sensors?","a":"Yes — with the 0-10V dimming versions paired with high-bay motion sensors, unoccupied aisles drop to a low level and return to full output on approach. The energy savings usually pay for the sensors within a year."}]'::jsonb, '/images/extras/1.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('industrial-strip-4ft-40w', 'GSW-INDUSTRIAL', 'Industrial LED Strip Fixture 4ft – 40W', 'industrial-lighting', 'led-linear-strip-light', 39, 49, false, 'Rugged industrial striplight with wire guard option for plants, shops and maintenance bays.', 'Rugged industrial striplight with wire guard option for plants, shops and maintenance bays.', '["40W | 5200 lm","5000K daylight","120-277V, row mounting","cULus | optional wire guard"]'::jsonb, 'in-stock', 'Industrial LED Strip Fixture 4ft –…', 'Buy the Industrial LED Strip Fixture 4ft – 40W wholesale in Canada. 40W | 5200 lm — cULus/DLC certified, flat $30 shipping.', 'The Industrial LED Strip Fixture 4ft – 40W is an industrial-grade LED strip fixture for plants, shops and utility spaces that need tough, serviceable lighting. 40W | 5200 lm in a housing that accepts wire guards and links into continuous rows. Maintenance crews and plant electricians across Canada order industrial striplights from GSW at wholesale pricing with parts support after the sale.', '[{"q":"Can I get these with wire guards?","a":"Yes — most industrial strip fixtures accept optional wire guards for impact protection in shops and plants where forklifts and ladders are moving. Add them to your order by phone."},{"q":"Are replacement drivers and boards available?","a":"That is the advantage of buying from a real distributor: drivers, boards and lenses for the fixtures we sell are stocked as parts, so a damaged unit is repaired — not landfilled."}]'::jsonb, '/images/extras/wkiaivjqmycfsa2taaemtkibiwe630.webp');
