insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('reno-exit-signs-amp-emergency-lighting', 'RENO-EXITSIGNSAMPEMERGENCYLIG', 'EXIT SIGNS &amp; EMERGENCY LIGHTING', 'commercial-lighting', 'exit-emergency-led-lighting', 0, null, false, 'Exit Signs &amp; Emergency Lighting specifically designed to illuminate the path to egress and guide building occupants to safety.', 'Exit Signs &amp; Emergency Lighting specifically designed to illuminate the path to egress and guide building occupants to safety.', '["Genuine Reno Lighting product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'EXIT SIGNS &amp; EMERGENCY LIGHTING', 'Buy the EXIT SIGNS &amp; EMERGENCY LIGHTING wholesale in Canada. Genuine Reno Lighting product — cULus/DLC certified, flat $30 shipping.', 'The EXIT SIGNS &amp; EMERGENCY LIGHTING is a cULus-listed exit and emergency lighting unit for code-compliant egress. Genuine Reno Lighting product with 90-minute battery backup and universal mounting for walls and ceilings. Electrical contractors across Canada buy life-safety lighting from GSW because every unit we ship carries the certifications inspectors look for — and we stock them in depth.', '[{"q":"Does this meet Ontario Fire Code?","a":"Yes — our exit signs and emergency units are cULus listed to CSA 22.2 No. 141 with 90-minute battery backup, meeting Ontario Fire Code and OBC egress requirements. Certificates are available on request."},{"q":"Red or green letters?","a":"Ontario accepts both, but red is the most common choice locally. Most of our units accept either legend — tell us your preference when ordering."}]'::jsonb, '/images/products/brand-reno-exit-signs-amp-emergency-lighting.webp');
