insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('etlin-flh5s', 'ETLIN-FLH5S', 'FLH5S', 'commercial-lighting', 'led-flood-light', 0, null, false, 'SQUARE AND ROUND POLE WITH SLIP-FITTER FUNCTION FOR FLH5S LED FLOOD LIGHT', 'SQUARE AND ROUND POLE WITH SLIP-FITTER FUNCTION FOR FLH5S LED FLOOD LIGHT', '["Genuine Etlin Daniels product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'FLH5S Canada', 'Buy the FLH5S wholesale in Canada. Genuine Etlin Daniels product — cULus/DLC certified, flat $30 shipping.', 'The FLH5S is a high-output LED flood light engineered for large areas — parking lots, yards, facades and sports surfaces. Genuine Etlin Daniels product with precision optics that put light on the target, not the neighbours. GSW is a Canadian wholesale LED lighting supplier, so flood lights ship flat-rate across the country and are always available for pickup at our Mississauga counter.', '[{"q":"How do I choose wattage for a parking lot?","a":"As a rule of thumb, 100W–150W LED replaces a 400W metal halide shoebox or flood. Tell us the pole height and spacing and we will run a quick layout to confirm foot-candles before you commit."},{"q":"Are these lights dimmable or motion-controllable?","a":"Most models accept 0-10V dimming and pair with motion sensors or photocells for after-hours energy savings. We stock compatible controls."}]'::jsonb, '/images/products/brand-etlin-flh5s.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('etlin-rtbpsmk', 'ETLIN-RTBPSMK', 'RTBPSMK', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Surface Mount Kit for RTPBP 2 Ft x 2 Ft LED Flat Panel', 'Surface Mount Kit for RTPBP 2 Ft x 2 Ft LED Flat Panel', '["Genuine Etlin Daniels product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'RTBPSMK Canada', 'Buy the RTBPSMK wholesale in Canada. Genuine Etlin Daniels product — cULus/DLC certified, flat $30 shipping.', 'The RTBPSMK is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine Etlin Daniels product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, '/images/products/brand-etlin-rtbpsmk.webp');
