insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('etlin-flh5s-2', 'ETLIN-FLH5S2', 'FLH5S', 'commercial-lighting', 'led-flood-light', 0, null, false, 'Square and Round Pole Mount for FLH5S LED Flood Light', 'Square and Round Pole Mount for FLH5S LED Flood Light', '["Genuine Etlin Daniels product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'FLH5S Canada', 'Buy the FLH5S wholesale in Canada. Genuine Etlin Daniels product — cULus/DLC certified, flat $30 shipping.', 'The FLH5S is a high-output LED flood light engineered for large areas — parking lots, yards, facades and sports surfaces. Genuine Etlin Daniels product with precision optics that put light on the target, not the neighbours. GSW is a Canadian wholesale LED lighting supplier, so flood lights ship flat-rate across the country and are always available for pickup at our Mississauga counter.', '[{"q":"How do I choose wattage for a parking lot?","a":"As a rule of thumb, 100W–150W LED replaces a 400W metal halide shoebox or flood. Tell us the pole height and spacing and we will run a quick layout to confirm foot-candles before you commit."},{"q":"Are these lights dimmable or motion-controllable?","a":"Most models accept 0-10V dimming and pair with motion sensors or photocells for after-hours energy savings. We stock compatible controls."}]'::jsonb, '/images/products/brand-etlin-flh5s-2.webp');
