insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-shop', 'CANOLIGHT-SHOP', 'Shop', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'Products Archive - Canolight', 'Products Archive - Canolight', '["Genuine Canolight product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Shop Canada', 'Buy the Shop wholesale in Canada. Genuine Canolight product — cULus/DLC certified, flat $30 shipping.', 'The Shop is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine Canolight product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, null);
