insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-6-quot-commercial-led-downlight-30w-5', 'VOTATEC-6QUOTCOMMERCIALLEDDOWNLI', '6&quot; Commercial LED Downlight, 30W 5', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '6&quot; commercial LED downlight, 12W to 30W selectable, 125Lm/W, 5-CCT (2700K to 5000K), AC120-347V, wet-location rated, CRI &gt;90. Request a quote.', '6&quot; commercial LED downlight, 12W to 30W selectable, 125Lm/W, 5-CCT (2700K to 5000K), AC120-347V, wet-location rated, CRI &gt;90. Request a quote.', '["Genuine Votatec product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '6&quot; Commercial LED Downlight,…', 'Buy the 6&quot; Commercial LED Downlight, 30W 5 wholesale in Canada. Genuine Votatec product — cULus/DLC certified, flat $30 shipping.', 'The 6&quot; Commercial LED Downlight, 30W 5 is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine Votatec product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-6-quot-commercial-led-downlight-30w-5.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-4-quot-commercial-led-downlight', 'VOTATEC-4QUOTCOMMERCIALLEDDOWNLI', '4&quot; Commercial LED Downlight', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '4&quot; recessed commercial LED downlight, 5-way CCT selectable and adjustable power. For offices, retail, and institutional projects. Request a quote.', '4&quot; recessed commercial LED downlight, 5-way CCT selectable and adjustable power. For offices, retail, and institutional projects. Request a quote.', '["Genuine Votatec product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '4&quot; Commercial LED Downlight', 'Buy the 4&quot; Commercial LED Downlight wholesale in Canada. Genuine Votatec product — cULus/DLC certified, flat $30 shipping.', 'The 4&quot; Commercial LED Downlight is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine Votatec product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-4-quot-commercial-led-downlight.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-23', 'CANOLIGHT-CL23', 'CL', 'residential-lighting', 'led-strip-light', 0, null, false, 'LL1 Up &amp; Down LED Linear Light Accessory - PC Cover 25ft/roll Dimensions available in catalogue sheet', 'LL1 Up &amp; Down LED Linear Light Accessory - PC Cover 25ft/roll Dimensions available in catalogue sheet', '["Genuine Canolight product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL Canada', 'Buy the CL wholesale in Canada. Genuine Canolight product — cULus/DLC certified, flat $30 shipping.', 'The CL is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine Canolight product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-canolight-cl-23.webp');
