insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-t45-led-filament-bulb-7w-e26-3', 'VOTATEC-T45LEDFILAMENTBULB7WE263', 'T45 LED Filament Bulb, 7W E26 3', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'T45 LED filament bulb, 7W, 700Lm, 3000K/4000K/5000K, E26 base, 360 beam, 120V, dimmable, CRI &gt;80, 50,000-hour life. Vintage tubular. Get a quote.', 'T45 LED filament bulb, 7W, 700Lm, 3000K/4000K/5000K, E26 base, 360 beam, 120V, dimmable, CRI &gt;80, 50,000-hour life. Vintage tubular. Get a quote.', '["Genuine Votatec product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'T45 LED Filament Bulb, 7W E26 3', 'Buy the T45 LED Filament Bulb, 7W E26 3 wholesale in Canada. Genuine Votatec product — cULus/DLC certified, flat $30 shipping.', 'The T45 LED Filament Bulb, 7W E26 3 is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine Votatec product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine Votatec product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-votatec-t45-led-filament-bulb-7w-e26-3.webp');
