insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('greenlite-wi-2', 'GREENLITE-WI2', 'Wi', 'residential-lighting', 'led-strip-light', 0, null, false, 'Wi genuine greenlite product, available wholesale at Green Solar World Inc.', 'Wi by greenlite. Call for wholesale pricing.', '["Genuine Greenlite product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Wi Canada', 'Buy the Wi wholesale in Canada. Genuine Greenlite product — cULus/DLC certified, flat $30 shipping.', 'The Wi is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine Greenlite product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-greenlite-wi-2.webp');
