insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('greenlite-10w-6-quot-5cct-retrofit-downlight', 'GREENLITE-10W6QUOT5CCTRETROFITDOWN', '10W 6&quot; 5CCT Retrofit Downlight', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '10W 6&quot; 5CCT Retrofit Downlight genuine greenlite product, available wholesale at Green Solar World Inc.', '10W 6&quot; 5CCT Retrofit Downlight by greenlite. Call for wholesale pricing.', '["Genuine Greenlite product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '10W 6&quot; 5CCT Retrofit Downlight', 'Buy the 10W 6&quot; 5CCT Retrofit Downlight wholesale in Canada. Genuine Greenlite product — cULus/DLC certified, flat $30 shipping.', 'The 10W 6&quot; 5CCT Retrofit Downlight is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine Greenlite product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-greenlite-10w-6-quot-5cct-retrofit-downlight.webp');
