insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-busguard', 'RACKATIERS-ATIERSBUSGUARD', 'BusGuard', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Secure unused panel openings with BusGuard Panel Filler. Stays in place, reduces shock and arc flash risk, and installs fast.', 'Secure unused panel openings with BusGuard Panel Filler. Stays in place, reduces shock and arc flash risk, and installs fast.', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'BusGuard Canada', 'Buy the BusGuard wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The BusGuard is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine Rack-A-Tiers product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, '/images/products/brand-rack-a-tiers-busguard.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-allen-head-7-piece-driver-bit-kit', 'RACKATIERS-ATIERSALLENHEAD7PIECEDRI', 'Allen Head 7 Piece Driver Bit Kit', 'commercial-lighting', 'transformer', 0, null, false, 'Features: Industrial grade bits. Extremely durable. 1/4&quot; hex shank. Quick connect design. Hard to find 6&quot; length.', 'Features: Industrial grade bits. Extremely durable. 1/4&quot; hex shank. Quick connect design. Hard to find 6&quot; length.', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Allen Head 7 Piece Driver Bit Kit', 'Buy the Allen Head 7 Piece Driver Bit Kit wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The Allen Head 7 Piece Driver Bit Kit is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine Rack-A-Tiers product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-allen-head-7-piece-driver-bit-kit.webp');
