insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-efergy-125a-current-sensor', 'RACKATIERS-ATIERSEFERGY125ACURRENTS', 'Efergy 125A Current Sensor', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, 'Additional sensor for measuring current up to 125 amperes. Works with the Elite Classic. Perfect for whole house applications where a 100 amp services is instal', 'Additional sensor for measuring current up to 125 amperes. Works with the Elite Classic. Perfect for whole house applications where a 100 amp services is installed. Split core design easily [ ]', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Efergy 125A Current Sensor Canada', 'Buy the Efergy 125A Current Sensor wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The Efergy 125A Current Sensor is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine Rack-A-Tiers product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-rack-a-tiers-efergy-125a-current-sensor.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-copper-wire-stripper-jr-parts', 'RACKATIERS-ATIERSCOPPERWIRESTRIPPER', 'Copper Wire Stripper Jr. Parts', 'residential-lighting', 'led-strip-light', 0, null, false, 'Please note: These products are special order and may take 2-3 weeks for delivery.', 'Please note: These products are special order and may take 2-3 weeks for delivery.', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Copper Wire Stripper Jr. Parts', 'Buy the Copper Wire Stripper Jr. Parts wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The Copper Wire Stripper Jr. Parts is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine Rack-A-Tiers product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-rack-a-tiers-copper-wire-stripper-jr-parts.webp');
