insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-1-light-blue-phillips-bit', 'RACKATIERS-ATIERS1LIGHTBLUEPHILLIPS', '#1 Light Blue Phillips Bit', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'Color coding? It s so simple, but it works. Racky Bits are easier to use and harder to lose, saving you a ton of time. Mfg Note: The most popular color [ ]', 'Color coding? It s so simple, but it works. Racky Bits are easier to use and harder to lose, saving you a ton of time. Mfg Note: The most popular color [ ]', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '#1 Light Blue Phillips Bit Canada', 'Buy the #1 Light Blue Phillips Bit wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The #1 Light Blue Phillips Bit is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine Rack-A-Tiers product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-rack-a-tiers-1-light-blue-phillips-bit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-ez-bulb-kit', 'RACKATIERS-ATIERSEZBULBKIT', 'EZ Bulb Kit', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'The EZ Bulb makes it effortless to change and replace par LED lamps with simple, easy to use lamp changers that fit on any universal extension pole. The EZ Bulb', 'The EZ Bulb makes it effortless to change and replace par LED lamps with simple, easy to use lamp changers that fit on any universal extension pole. The EZ Bulb [ ]', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'EZ Bulb Kit Canada', 'Buy the EZ Bulb Kit wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The EZ Bulb Kit is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine Rack-A-Tiers product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine Rack-A-Tiers product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-rack-a-tiers-ez-bulb-kit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-robertson-square-screw-drivers', 'RACKATIERS-ATIERSROBERTSONSQUARESCR', 'Robertson Square Screw Drivers', 'commercial-lighting', 'transformer', 0, null, false, 'Features: Great Quality. Great Fit. Most Torque. Best Grip.', 'Features: Great Quality. Great Fit. Most Torque. Best Grip.', '["Genuine Rack-A-Tiers product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Robertson Square Screw Drivers', 'Buy the Robertson Square Screw Drivers wholesale in Canada. Genuine Rack-A-Tiers product — cULus/DLC certified, flat $30 shipping.', 'The Robertson Square Screw Drivers is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine Rack-A-Tiers product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-robertson-square-screw-drivers.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('dawnray-category-flat-panel', 'DAWNRAY-CATEGORYFLATPANEL', 'Category Flat Panel', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Flat Panel [the-post-grid id=&quot;1503&quot; title=&quot;Flat Panel&quot;]', 'Flat Panel [the-post-grid id=&quot;1503&quot; title=&quot;Flat Panel&quot;]', '["Genuine DawnRay product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Category Flat Panel Canada', 'Buy the Category Flat Panel wholesale in Canada. Genuine DawnRay product — cULus/DLC certified, flat $30 shipping.', 'The Category Flat Panel is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine DawnRay product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('dawnray-category-strip-light', 'DAWNRAY-CATEGORYSTRIPLIGHT', 'Category Strip Light', 'residential-lighting', 'led-strip-light', 0, null, false, 'Strip Light [the-post-grid id=&quot;1504&quot; title=&quot;Strip Light&quot;]', 'Strip Light [the-post-grid id=&quot;1504&quot; title=&quot;Strip Light&quot;]', '["Genuine DawnRay product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Category Strip Light Canada', 'Buy the Category Strip Light wholesale in Canada. Genuine DawnRay product — cULus/DLC certified, flat $30 shipping.', 'The Category Strip Light is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine DawnRay product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('dawnray-order-tracking', 'DAWNRAY-ORDERTRACKING', 'Order Tracking', 'commercial-lighting', 'led-track-light', 0, null, false, 'Order Tracking genuine dawnray product, available wholesale at Green Solar World Inc.', 'Order Tracking by dawnray. Call for wholesale pricing.', '["Genuine DawnRay product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Order Tracking Canada', 'Buy the Order Tracking wholesale in Canada. Genuine DawnRay product — cULus/DLC certified, flat $30 shipping.', 'The Order Tracking is a precision LED track light for retail displays, galleries and hospitality spaces. Genuine DawnRay product with the aiming flexibility merchandisers need and the colour quality that makes product pop. Retail fit-out contractors across Toronto buy track lighting wholesale from GSW, with H/J/L adapter compatibility confirmed before you order.', '[{"q":"Which track system does it fit?","a":"Our track heads are available with H-type, J-type and L-type adapters to match existing track. New installs typically use H-type — we stock track, connectors and heads as a complete system."},{"q":"What beam angle should I choose?","a":"Narrow 15–24° spots highlight individual products; 36–40° accents cover wall sections; floods wash general areas. Mixed angles on one run give the layered look designers want."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('dawnray-track-order', 'DAWNRAY-TRACKORDER', 'Track Order', 'commercial-lighting', 'led-track-light', 0, null, false, 'Track Order genuine dawnray product, available wholesale at Green Solar World Inc.', 'Track Order by dawnray. Call for wholesale pricing.', '["Genuine DawnRay product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Track Order Canada', 'Buy the Track Order wholesale in Canada. Genuine DawnRay product — cULus/DLC certified, flat $30 shipping.', 'The Track Order is a precision LED track light for retail displays, galleries and hospitality spaces. Genuine DawnRay product with the aiming flexibility merchandisers need and the colour quality that makes product pop. Retail fit-out contractors across Toronto buy track lighting wholesale from GSW, with H/J/L adapter compatibility confirmed before you order.', '[{"q":"Which track system does it fit?","a":"Our track heads are available with H-type, J-type and L-type adapters to match existing track. New installs typically use H-type — we stock track, connectors and heads as a complete system."},{"q":"What beam angle should I choose?","a":"Narrow 15–24° spots highlight individual products; 36–40° accents cover wall sections; floods wash general areas. Mixed angles on one run give the layered look designers want."}]'::jsonb, null);
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('dawnray-learn-flat-panel', 'DAWNRAY-LEARNFLATPANEL', 'Learn Flat Panel', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Super Slim Commercial LED Panel Flat Panel Show Me More', 'Super Slim Commercial LED Panel Flat Panel Show Me More', '["Genuine DawnRay product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Learn Flat Panel Canada', 'Buy the Learn Flat Panel wholesale in Canada. Genuine DawnRay product — cULus/DLC certified, flat $30 shipping.', 'The Learn Flat Panel is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine DawnRay product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, null);
